import { Graph, Layouts } from "retiam/graphs";
const graph = new Graph({ isDirected: true });
graph.addNode("A", { label: "Start" });
graph.addNode("B", { label: "Work" });
graph.addNode("C", { label: "Done" });
graph.addEdge("A", "B");
graph.addEdge("B", "C");
graph.applyLayout(Layouts.circular(["A", "B", "C"], 3));
this.add(graph);
await this.play(graph.highlightPath(["A", "B", "C"]));

import { Automaton } from "retiam/graphs";
const automaton = new Automaton();
automaton.addState("q0", { isStart: true });
automaton.addState("q1", { isAccepting: true });
automaton.addTransition("q0", "q1", "1");
automaton.addTransition("q1", "q1", "1");
console.log(automaton.accepts("111"));
